ALTER TABLE branches ADD CONSTRAINT branch_tenant_identity UNIQUE(restaurant_id,id);
CREATE TABLE commerce_settings(restaurant_id uuid PRIMARY KEY REFERENCES restaurants(id),version integer NOT NULL DEFAULT 0,content jsonb NOT NULL);
CREATE TABLE plans(code text PRIMARY KEY,name text NOT NULL,ordering boolean NOT NULL,reservations boolean NOT NULL);
INSERT INTO plans VALUES('basic','Website only',false,false),('pilot','Controlled pilot',true,true);
CREATE TABLE tenant_subscriptions(restaurant_id uuid PRIMARY KEY REFERENCES restaurants(id),plan_code text NOT NULL REFERENCES plans(code),status text NOT NULL CHECK(status IN('manual','trial','inactive')),trial_ends_at timestamptz,version integer NOT NULL DEFAULT 0);
CREATE TABLE commerce_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL REFERENCES restaurants(id),token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 days',UNIQUE(restaurant_id,id));
CREATE TABLE customer_profiles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL REFERENCES restaurants(id),user_id uuid NOT NULL REFERENCES users(id),content jsonb NOT NULL,UNIQUE(restaurant_id,user_id),UNIQUE(restaurant_id,id));
CREATE TABLE customer_addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,customer_id uuid NOT NULL,content jsonb NOT NULL,FOREIGN KEY(restaurant_id,customer_id) REFERENCES customer_profiles(restaurant_id,id));
CREATE TABLE carts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,session_id uuid NOT NULL,user_id uuid REFERENCES users(id),version integer NOT NULL DEFAULT 0,lines jsonb NOT NULL DEFAULT '[]',expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days',submitted boolean NOT NULL DEFAULT false,FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id),FOREIGN KEY(restaurant_id,session_id) REFERENCES commerce_sessions(restaurant_id,id),UNIQUE(restaurant_id,id));
CREATE INDEX cart_scope ON carts(restaurant_id,session_id,user_id);
CREATE TABLE checkout_quotes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,cart_id uuid NOT NULL,session_id uuid NOT NULL,user_id uuid REFERENCES users(id),cart_version integer NOT NULL,settings_version integer NOT NULL,revision_id uuid NOT NULL,content jsonb NOT NULL,expires_at timestamptz NOT NULL DEFAULT now()+interval '5 minutes',FOREIGN KEY(restaurant_id,cart_id) REFERENCES carts(restaurant_id,id),FOREIGN KEY(restaurant_id,session_id) REFERENCES commerce_sessions(restaurant_id,id),FOREIGN KEY(restaurant_id,revision_id) REFERENCES website_revisions(restaurant_id,id),UNIQUE(restaurant_id,id));
CREATE TABLE orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,cart_id uuid NOT NULL UNIQUE,quote_id uuid NOT NULL,session_id uuid NOT NULL,user_id uuid REFERENCES users(id),reference text NOT NULL,status text NOT NULL CHECK(status IN('PENDING','CONFIRMED','PREPARING','READY','COMPLETED','CANCELLED','REJECTED','EXPIRED')),payment_status text NOT NULL CHECK(payment_status IN('UNPAID','PENDING','UNKNOWN','PAID','FAILED')),method text NOT NULL CHECK(method IN('pay_at_pickup','test_online')),currency varchar(3) NOT NULL,total bigint NOT NULL CHECK(total>=0),snapshot jsonb NOT NULL,contact jsonb NOT NULL,version integer NOT NULL DEFAULT 0,cancellation_requested boolean NOT NULL DEFAULT false,preparation_minutes integer NOT NULL DEFAULT 15,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,expires_at timestamptz NOT NULL DEFAULT now()+interval '30 minutes',FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id),FOREIGN KEY(restaurant_id,cart_id) REFERENCES carts(restaurant_id,id),FOREIGN KEY(restaurant_id,quote_id) REFERENCES checkout_quotes(restaurant_id,id),FOREIGN KEY(restaurant_id,session_id) REFERENCES commerce_sessions(restaurant_id,id),UNIQUE(restaurant_id,id),UNIQUE(restaurant_id,reference));
CREATE INDEX order_worklist ON orders(restaurant_id,created_at DESC,status);
CREATE INDEX order_customer ON orders(user_id,created_at DESC);
CREATE TABLE order_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,order_id uuid NOT NULL,snapshot jsonb NOT NULL,FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id));
CREATE TABLE order_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,restaurant_id uuid NOT NULL,order_id uuid NOT NULL,status text NOT NULL,actor_id uuid REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id));
CREATE TABLE checkout_operations(restaurant_id uuid NOT NULL,session_id uuid NOT NULL,scope text NOT NULL,key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(restaurant_id,scope,key),FOREIGN KEY(restaurant_id,session_id) REFERENCES commerce_sessions(restaurant_id,id));
CREATE TABLE payment_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,provider text NOT NULL,merchant text NOT NULL,provider_reference text NOT NULL,status text NOT NULL DEFAULT 'PENDING',attempts integer NOT NULL DEFAULT 0,last_error text,reconcile_after timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),UNIQUE(provider,merchant,provider_reference),UNIQUE(restaurant_id,id));
CREATE TABLE payment_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,order_id uuid NOT NULL UNIQUE,provider_reference text NOT NULL,amount bigint NOT NULL CHECK(amount>=0),currency varchar(3) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id));
CREATE TABLE refund_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,order_id uuid NOT NULL,amount bigint NOT NULL CHECK(amount>0),status text NOT NULL CHECK(status IN('PENDING','CONFIRMED','FAILED')),reason text NOT NULL,actor_id uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),confirmed_at timestamptz,FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id),UNIQUE(restaurant_id,id));
CREATE TABLE provider_events(provider text NOT NULL,merchant text NOT NULL,event_id text NOT NULL,restaurant_id uuid NOT NULL REFERENCES restaurants(id),fingerprint text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(provider,merchant,event_id));
CREATE TABLE test_provider_ledger(reference text PRIMARY KEY,merchant text NOT NULL,amount bigint NOT NULL,currency varchar(3) NOT NULL,status text NOT NULL DEFAULT 'PENDING');
CREATE TABLE reservations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL,branch_id uuid NOT NULL,session_id uuid NOT NULL,user_id uuid REFERENCES users(id),reference text NOT NULL,status text NOT NULL CHECK(status IN('PENDING','CONFIRMED','DECLINED','CANCELLED','EXPIRED','SEATED','COMPLETED','NO_SHOW')),start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,party integer NOT NULL CHECK(party>0),contact jsonb NOT NULL,hold_expires_at timestamptz NOT NULL,version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),CHECK(end_at>start_at),FOREIGN KEY(restaurant_id,branch_id) REFERENCES branches(restaurant_id,id),FOREIGN KEY(restaurant_id,session_id) REFERENCES commerce_sessions(restaurant_id,id),UNIQUE(restaurant_id,id),UNIQUE(restaurant_id,reference));
CREATE INDEX reservation_overlap ON reservations(restaurant_id,branch_id,start_at,end_at);
CREATE TABLE reservation_allocations(restaurant_id uuid NOT NULL,reservation_id uuid NOT NULL,start_at timestamptz NOT NULL,end_at timestamptz NOT NULL,covers integer NOT NULL CHECK(covers>0),PRIMARY KEY(restaurant_id,reservation_id),FOREIGN KEY(restaurant_id,reservation_id) REFERENCES reservations(restaurant_id,id),CHECK(end_at>start_at));
CREATE TABLE reservation_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,restaurant_id uuid NOT NULL,reservation_id uuid NOT NULL,status text NOT NULL,actor_id uuid REFERENCES users(id),reason text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(restaurant_id,reservation_id) REFERENCES reservations(restaurant_id,id));
CREATE TABLE outbox_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),restaurant_id uuid NOT NULL REFERENCES restaurants(id),dedup_key text NOT NULL UNIQUE,kind text NOT NULL,payload jsonb NOT NULL,state text NOT NULL DEFAULT 'PENDING' CHECK(state IN('PENDING','LEASED','DONE','FAILED')),attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_token uuid,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_due ON outbox_events(state,available_at);
CREATE TABLE notification_deliveries(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,event_id uuid NOT NULL REFERENCES outbox_events(id),attempt integer NOT NULL,status text NOT NULL,error text,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,attempt));
CREATE TABLE in_app_notifications(event_id uuid PRIMARY KEY REFERENCES outbox_events(id),restaurant_id uuid NOT NULL REFERENCES restaurants(id),user_id uuid REFERENCES users(id),session_id uuid REFERENCES commerce_sessions(id),content jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO permissions(code,description,module) VALUES('orders:read','View tenant orders','orders'),('orders:process','Process fulfillment','orders'),('orders:cancel','Cancel orders','orders'),('payments:manage','Record collections and refunds','payments'),('reservations:manage','Manage reservations','reservations'),('reports:read','Read reports','reports');
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.restaurant_id IS NULL AND ((r.name IN('owner','manager') AND p.module IN('orders','payments','reservations','reports')) OR (r.name='staff' AND p.code IN('orders:read','orders:process','reservations:manage'))) ON CONFLICT DO NOTHING;
